shader_type canvas_item;
render_mode unshaded;
uniform vec2 card_size = vec2(250.0, 352.0);
uniform float layout_scale = 1.0;
uniform float progress = 1.0;
varying vec2 card_point;
void vertex() {
	card_point = VERTEX;
}
void fragment() {
	vec4 frame = texture(TEXTURE, UV);
	vec2 edge_distance = min(card_point, card_size - card_point);
	float edge = 1.0 - smoothstep(3.0 * layout_scale, 11.0 * layout_scale, min(edge_distance.x, edge_distance.y));
	float metal = smoothstep(0.12, 0.57, dot(frame.rgb, vec3(0.299, 0.587, 0.114)));
	vec2 face = card_point / max(card_size, vec2(1.0));
	float sweep = max(0.0, 1.0 - abs(face.x + face.y * 0.24 - mix(-0.28, 1.52, progress)) / 0.25);
	float envelope = sin(clamp(progress, 0.0, 1.0) * 3.14159265);
	COLOR = vec4(vec3(1.0, 0.91, 0.72), frame.a * edge * metal * sweep * sweep * envelope * 0.70);
}

shader_type canvas_item;
render_mode blend_add, unshaded;
uniform vec4 glow_color : source_color = vec4(1.0);
uniform vec2 gem_center = vec2(125.0, 337.0);
uniform float gem_radius = 14.0;
uniform float strength = 1.0;
uniform float rays = 0.0;
uniform float sparkle = 0.0;
uniform float phase = 0.0;
uniform float animate = 1.0;
varying vec2 local;
void vertex() {
	local = VERTEX;
}
void fragment() {
	float t = TIME * animate + phase;
	vec2 d = (local - gem_center) / gem_radius;
	d.y *= 0.92;
	float r = length(d);
	float breath = 0.74 + 0.20 * sin(t * 2.1) + 0.06 * sin(t * 5.7 + 1.3);
	float core = exp(-r * r * 1.6) * 0.62;
	float halo = exp(-r * 1.05) * 0.70;
	float a = atan(d.y, d.x);
	float beams = pow(max(0.0, cos(a * 3.0 + t * 0.31)), 22.0) + 0.7 * pow(max(0.0, cos(a * 4.0 - t * 0.23 + 1.1)), 30.0);
	float ray = beams * exp(-r * 0.95) * smoothstep(0.55, 1.25, r) * rays;
	float shimmer = 0.5 + 0.5 * sin(d.x * 3.1 + d.y * 4.7 - t * 3.3);
	float cycle = fract((t + 0.9) / 4.3);
	float flash = pow(max(0.0, 1.0 - abs(cycle - 0.5) * 7.0), 2.0);
	vec2 g = d - vec2(-0.30, -0.42);
	float star = (exp(-abs(g.x) * 16.0 - abs(g.y) * 1.7) + exp(-abs(g.y) * 16.0 - abs(g.x) * 1.7)) * exp(-length(g) * 0.9);
	float glint = (star + exp(-dot(g, g) * 30.0)) * flash * sparkle;
	float energy = (core * (0.82 + 0.18 * shimmer) + halo + ray) * breath + glint * 1.3;
	vec3 hot = mix(glow_color.rgb, vec3(1.0, 0.97, 0.90), clamp(core * 0.25 + glint * 0.8, 0.0, 1.0));
	COLOR = vec4(hot, clamp(energy * strength * glow_color.a, 0.0, 1.0));
}

shader_type canvas_item;
render_mode blend_premul_alpha, unshaded;

uniform vec2 pool_center = vec2(0.5, 0.44);
uniform vec2 pool_radius = vec2(0.36, 0.30);
uniform vec4 pool_color : source_color = vec4(1.0, 0.60, 0.28, 1.0);
uniform float pool_strength = 0.17;
uniform vec4 vignette_color : source_color = vec4(0.018, 0.012, 0.010, 1.0);
uniform float vignette_strength = 0.80;
uniform float vignette_inner = 0.30;
uniform float vignette_outer = 1.02;
uniform float aspect = 1.7778;
uniform float hurt = 0.0;
uniform vec4 hurt_color : source_color = vec4(0.55, 0.05, 0.03, 1.0);

void fragment() {
	vec2 q = (UV - vec2(0.5)) * 2.0;
	float edge = length(q * vec2(1.0, 0.92)) / 1.36;
	float vignette = smoothstep(vignette_inner, vignette_outer, edge) * vignette_strength;
	float hurt_edge = smoothstep(0.42, 1.05, edge) * hurt;
	vignette = max(vignette, hurt_edge * 0.85);
	vec3 vignette_tint = mix(vignette_color.rgb, hurt_color.rgb, clamp(hurt_edge * 1.4, 0.0, 1.0));
	vec2 pc = (UV - pool_center) / pool_radius;
	pc.x *= 1.0;
	float pool = exp(-dot(pc, pc) * 1.45) * pool_strength;
	vec3 glow = pool_color.rgb * pool;
	COLOR = vec4(glow * (1.0 - vignette) + vignette_tint * vignette, vignette);
}

shader_type canvas_item;
render_mode unshaded;

uniform vec2 death_center = vec2(0.32, 0.62);
uniform vec2 aspect_scale = vec2(1.7777778, 1.0);
uniform float engulf_progress : hint_range(0.0, 1.0) = 0.0;
uniform float shroud_alpha : hint_range(0.0, 1.0) = 0.90;

float cubic_ease(float x) {
	return x < 0.5 ? 4.0 * x * x * x : 1.0 - pow(-2.0 * x + 2.0, 3.0) * 0.5;
}

void fragment() {
	vec2 delta = (UV - death_center) * aspect_scale;
	float distance_from_death = length(delta);
	float angle = atan(delta.y, delta.x);
	float eased = cubic_ease(engulf_progress);
	float irregularity = sin(angle * 5.0 + eased * 2.2) * 0.018;
	irregularity += sin(angle * 9.0 - eased * 1.4) * 0.009;
	float front_radius = mix(1.32, 0.175, eased) + irregularity * eased;
	float coverage = smoothstep(front_radius - 0.055, front_radius + 0.070, distance_from_death);
	float settled_halo = smoothstep(0.105, 0.285, distance_from_death);
	float alpha = shroud_alpha * coverage * mix(1.0, settled_halo, smoothstep(0.72, 1.0, eased));
	vec3 umbra = mix(vec3(0.020, 0.018, 0.030), vec3(0.035, 0.020, 0.055), 0.18 + 0.12 * sin(angle * 3.0));
	COLOR = vec4(umbra, alpha);
}

shader_type canvas_item;
render_mode unshaded, blend_add;

uniform vec2 death_center = vec2(0.32, 0.62);
uniform vec2 aspect_scale = vec2(1.7777778, 1.0);
uniform float glow_alpha : hint_range(0.0, 1.0) = 0.0;
uniform float pulse : hint_range(0.0, 1.0) = 0.5;

void fragment() {
	vec2 delta = (UV - death_center) * aspect_scale;
	float distance_from_death = length(delta);
	float warm_core = 1.0 - smoothstep(0.025, 0.175 + pulse * 0.010, distance_from_death);
	float soft_falloff = 1.0 - smoothstep(0.070, 0.300 + pulse * 0.012, distance_from_death);
	vec3 ember = vec3(1.0, 0.28, 0.055) * warm_core * 0.58;
	ember += vec3(0.90, 0.16, 0.035) * soft_falloff * 0.28;
	COLOR = vec4(ember, max(warm_core * 0.35, soft_falloff * 0.18) * glow_alpha);
}

shader_type canvas_item;
uniform sampler2D screen_texture : hint_screen_texture, filter_linear;
void fragment() {
 vec2 d = SCREEN_PIXEL_SIZE * 2.0;
 vec3 board = (texture(screen_texture, SCREEN_UV).rgb * 4.0
  + texture(screen_texture, SCREEN_UV + vec2(d.x,0)).rgb
  + texture(screen_texture, SCREEN_UV - vec2(d.x,0)).rgb
  + texture(screen_texture, SCREEN_UV + vec2(0,d.y)).rgb
  + texture(screen_texture, SCREEN_UV - vec2(0,d.y)).rgb) / 8.0;
 board = mix(vec3(dot(board,vec3(0.2126,0.7152,0.0722))), board, 0.7) * 0.35;
 float edge = clamp(length((UV-0.5)*2.0)/0.75,0.0,1.0);
 vec3 ink = mix(vec3(8,6,5)/255.0,vec3(4,3,2)/255.0,edge);
 COLOR = vec4(mix(board,ink,mix(0.35,0.86,edge)), COLOR.a);
}

shader_type canvas_item;
uniform float zoom = 1.0;
uniform vec2 rect_size = vec2(1062.0,728.0);
varying vec2 mask_uv;
varying vec4 painting_tint;
// Fragment COLOR already includes TEXTURE. Capture the untextured modulation
// in vertex(), so the painting is sampled once rather than RGB being squared.
void vertex() { mask_uv = VERTEX / rect_size; painting_tint = COLOR; }
void fragment() {
 vec4 paint = texture(TEXTURE,(UV-0.5)/zoom+0.5);
 float mask = clamp((1.0-mask_uv.x)/0.18,0.0,1.0)
  * clamp(mask_uv.y/0.07,0.0,1.0) * clamp((1.0-mask_uv.y)/0.10,0.0,1.0);
 COLOR = vec4(paint.rgb,paint.a*mask) * painting_tint;
}

shader_type canvas_item;

uniform vec4 top_color : source_color;
uniform vec4 high_color : source_color;
uniform vec4 mid_color : source_color;
uniform vec4 low_color : source_color;
uniform vec4 bottom_color : source_color;
uniform float gradient_offset = 0.0;
uniform float gradient_height = 1.0;
uniform float texture_strength = 0.12;

varying float local_y;
varying vec2 local_position;

float stone_hash(vec2 point) {
	return fract(sin(dot(point, vec2(127.1, 311.7))) * 43758.5453);
}

float stone_noise(vec2 point) {
	vec2 cell = floor(point);
	vec2 blend = fract(point);
	blend = blend * blend * (3.0 - 2.0 * blend);
	float top = mix(stone_hash(cell), stone_hash(cell + vec2(1.0, 0.0)), blend.x);
	float bottom = mix(stone_hash(cell + vec2(0.0, 1.0)), stone_hash(cell + vec2(1.0, 1.0)), blend.x);
	return mix(top, bottom, blend.y);
}

vec4 title_color_ramp(float position) {
	if (position <= 0.26) {
		return mix(top_color, high_color, clamp(position / 0.26, 0.0, 1.0));
	}
	if (position <= 0.56) {
		return mix(high_color, mid_color, clamp((position - 0.26) / 0.30, 0.0, 1.0));
	}
	if (position <= 0.80) {
		return mix(mid_color, low_color, clamp((position - 0.56) / 0.24, 0.0, 1.0));
	}
	return mix(low_color, bottom_color, clamp((position - 0.80) / 0.20, 0.0, 1.0));
}

void vertex() {
	local_y = VERTEX.y;
	local_position = VERTEX;
}

void fragment() {
	vec4 glyph = texture(TEXTURE, UV);
	float y = clamp((gradient_offset + local_y) / max(gradient_height, 1.0), 0.0, 1.0);
	vec4 ramp = title_color_ramp(y);
	float fine_grain = stone_noise(local_position / 5.0);
	float broad_grain = stone_noise(local_position / 19.0 + vec2(19.0, 7.0));
	float fleck_noise = stone_noise(local_position / 3.6 + vec2(5.0, 13.0));
	float dark_fleck = smoothstep(0.82, 0.97, fleck_noise);
	float pale_fleck = smoothstep(0.86, 0.98, stone_noise(local_position / 5.0 + vec2(31.0, 11.0)));
	float stone_value = (broad_grain - 0.5) * 0.82 + (fine_grain - 0.5) * 0.30;
	stone_value -= dark_fleck * 0.20;
	stone_value += pale_fleck * 0.10;
	ramp.rgb = clamp(ramp.rgb * (1.0 + stone_value * texture_strength), vec3(0.0), vec3(1.0));
	COLOR = vec4(ramp.rgb, glyph.a * COLOR.a);
}

shader_type canvas_item;
uniform float highlight_width = 1.0;
uniform float highlight_strength = 0.24;
uniform vec4 highlight_color : source_color = vec4(0.96, 0.79, 0.50, 1.0);

void fragment() {
	vec4 ink = COLOR;
	float neighbor = texture(TEXTURE, UV + dFdy(UV) * highlight_width).a;
	float inner_edge = clamp(ink.a - neighbor, 0.0, 1.0);
	COLOR = vec4(mix(ink.rgb, highlight_color.rgb, inner_edge * highlight_strength), ink.a);
}

shader_type canvas_item;
uniform float saturation = 1.0;
uniform float fade_start = 1.0;
uniform float content_width = 54.0;
varying vec2 local_point;
void vertex() { local_point = VERTEX; }
void fragment() {
	// In a canvas_item fragment, COLOR already holds texture * modulate.
	vec4 pixel = COLOR;
	float grey = dot(pixel.rgb, vec3(0.299, 0.587, 0.114));
	pixel.rgb = mix(vec3(grey), pixel.rgb, saturation);
	if (fade_start < 1.0) { pixel.a *= 1.0 - smoothstep(fade_start, 1.0, local_point.x / content_width); }
	COLOR = pixel;
}

shader_type canvas_item;

uniform float texture_strength = 0.12;
uniform float grain_scale = 4.0;

varying vec2 local_position;

float stone_hash(vec2 point) {
	return fract(sin(dot(point, vec2(127.1, 311.7))) * 43758.5453);
}

float stone_noise(vec2 point) {
	vec2 cell = floor(point);
	vec2 blend = fract(point);
	blend = blend * blend * (3.0 - 2.0 * blend);
	float top = mix(stone_hash(cell), stone_hash(cell + vec2(1.0, 0.0)), blend.x);
	float bottom = mix(stone_hash(cell + vec2(0.0, 1.0)), stone_hash(cell + vec2(1.0, 1.0)), blend.x);
	return mix(top, bottom, blend.y);
}

void vertex() {
	local_position = VERTEX;
}

void fragment() {
	vec4 glyph = texture(TEXTURE, UV);
	float scale = max(grain_scale, 1.0);
	float fine_grain = stone_noise(local_position / scale);
	float broad_grain = stone_noise(local_position / (scale * 3.8) + vec2(19.0, 7.0));
	float fleck_noise = stone_noise(local_position / (scale * 0.72) + vec2(5.0, 13.0));
	float dark_fleck = smoothstep(0.82, 0.97, fleck_noise);
	float pale_fleck = smoothstep(0.86, 0.98, stone_noise(local_position / scale + vec2(31.0, 11.0)));
	float stone_value = (broad_grain - 0.5) * 0.82 + (fine_grain - 0.5) * 0.30;
	stone_value -= dark_fleck * 0.20;
	stone_value += pale_fleck * 0.10;
	vec3 textured_color = clamp(COLOR.rgb * (1.0 + stone_value * texture_strength), vec3(0.0), vec3(1.0));
	COLOR = vec4(textured_color, glyph.a * COLOR.a);
}
